/**
 * 저장소 연동의 순수 판정(repository.ts)을 Rust로 옮기면서(ADR-191 3n) JS와 Rust가 다르게 읽기 쉬운 입력을 고정한다.
 * 기대값은 옮기기 전 TS 구현이 낸 값이다(JSON.stringify 글자 — 키 순서 포함). 1,500자를 넘는 기대값은 글자의 sha256만 적었다(`digest`).
 * "intended"를 적은 벡터만 옛 구현과 다르다: 자르는 자리가 서로게이트 쌍을 가르면 옛 구현은 짝 없는 서로게이트를 남기고, Rust는 napi 경계에서 U+FFFD가 된다
 * (그 벡터의 기대값은 옛 값의 짝 없는 서로게이트를 U+FFFD로 바꾼 것이다). 보이지 않는 글자는 \u 이스케이프로 적었다.
 * 특수한 값은 표시 객체로 적는다: {"$num":"NaN"}(NaN·Infinity·-0), {"$undef":true}(undefined), {"$repeat":[글자,n]}, {"$cat":[…]}(이어 붙임).
 *
 * 열린 쪽 벡터: parseRemote의 호스트 종류(`github.com.evil.com`·`evil.github.com`·`GitHub.com`·`github.com:443`·`github.com.`·userinfo·scp·ssh 포트·윈도우 경로·file:·
 * 공백 둘러싼 주소·빈 문자열·B_STUDIO_GIT_PROVIDER의 대소문자·앞뒤 공백), canCreatePullRequest의 빈 토큰(`??` 대 `||`), 관리 구간 표지(없음·하나만·뒤집힘·두 쌍·옛 모양)와
 * 60,000자 경계(마커 밖의 글 때문에 방이 59,954에서 ±1), 닫기 문구의 `\b` 경계와 큰 번호.
 */

interface Vector {
  fn: string;
  note: string;
  args: unknown[];
  intended?: string;
  expected?: unknown;
  digest?: string;
  length?: number;
  throws?: true;
}

function revive(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(revive);
  if (value !== null && typeof value === 'object') {
    const record = value as Record<string, unknown>;
    if ('$num' in record) return Number(record['$num']);
    if ('$undef' in record) return undefined;
    if ('$repeat' in record) {
      const [text, count] = record['$repeat'] as [string, number];
      return text.repeat(count);
    }
    if ('$cat' in record) return (record['$cat'] as unknown[]).map((part) => revive(part)).join('');
    return Object.fromEntries(Object.entries(record).map(([key, item]) => [key, revive(item)]));
  }
  return value;
}

/** 결과 글자: NaN·Infinity·-0은 표시 객체, undefined는 {"$undef":true} */
function encode(value: unknown): string {
  if (value === undefined) return '{"$undef":true}';
  return JSON.stringify(value, (_key, item: unknown) => (typeof item === 'number' && (!Number.isFinite(item) || Object.is(item, -0)) ? { $num: Object.is(item, -0) ? '-0' : String(item) } : item));
}

