describe('저장소 연동 벡터: 옛 TS가 낸 값과 같다', () => {
  it('벡터가 충분하고 이름이 겹치지 않는다', () => {
    expect(VECTORS.length).toBeGreaterThan(400);
    expect(VECTORS.filter((vector) => vector.intended).length).toBeGreaterThanOrEqual(4);
    expect(new Set(VECTORS.map((vector) => `${vector.fn}|${vector.note}|${JSON.stringify(vector.args).length}`)).size).toBeGreaterThan(VECTORS.length * 0.95);
  });

  for (const [index, vector] of VECTORS.entries()) {
    it(`${index} ${vector.fn}: ${vector.note}${vector.intended ? ' (의도한 차이)' : ''}`, () => {
      const impl = IMPLS[vector.fn];
      if (!impl) throw new Error(`알 수 없는 함수 ${vector.fn}`);
      const args = revive(vector.args) as unknown[];
      if (vector.throws) {
        expect(() => impl(...args)).toThrow();
        return;
      }
      const actual = encode(impl(...args));
      if (vector.digest !== undefined) {
        expect({ digest: createHash('sha256').update(actual).digest('hex'), length: actual.length }).toEqual({ digest: vector.digest, length: vector.length });
      } else {
        expect(actual).toBe(encode(revive(vector.expected)));
      }
    });
  }

  it('본문 길이 한도: 합친 본문은 마커 밖의 글을 지키면서 60,000자(UTF-16) 안이다', () => {
    const begin = '<!-- b-studio:begin -->';
    const end = '<!-- b-studio:end -->';
    for (const managed of ['x'.repeat(59953), 'x'.repeat(59954), 'x'.repeat(59955), '😀'.repeat(29978), 'a' + '😀'.repeat(30000), 'x'.repeat(70000)]) {
      const merged = repo.mergeManagedPullRequestBody(undefined, managed);
      expect(merged.length).toBeLessThanOrEqual(60000);
      expect(merged.startsWith(`${begin}\n`)).toBe(true);
      expect(merged.endsWith(`\n${end}`)).toBe(true);
    }
    const kept = repo.mergeManagedPullRequestBody(`앞 글\n${begin}\n옛\n${end}\n뒤 글`, 'x'.repeat(70000));
    expect(kept.startsWith('앞 글\n')).toBe(true);
    expect(kept.endsWith('\n뒤 글')).toBe(true);
    expect(kept.length).toBeLessThanOrEqual(60000);
  });

  it('호스트 종류: 토큰을 보내는 호스트(github·gitlab)는 호스트 이름이 정확히 같을 때만이다', () => {
    const kinds = (url: string): string => repo.parseRemote(url, {}).kind;
    for (const name of ['github.com.evil.com', 'evil.github.com', 'github.com.', 'xgithub.com', 'github.comx', 'github.co', 'api.github.com', 'github.com%2eevil.com']) {
      expect(kinds(`https://${name}/o/r`)).toBe('other');
      expect(kinds(`git@${name}:o/r`)).toBe('other');
    }
    for (const name of ['GitHub.com', 'GITHUB.COM']) {
      expect(kinds(`git@${name}:o/r`)).toBe('other'); // scp는 URL이 소문자로 바꿔 주지 않으므로 이름 그대로 견준다
    }
    expect(kinds('https://github.com@evil.com/o/r')).toBe('other');
    expect(kinds('https://evil.com@github.com/o/r')).toBe('github');
    expect(kinds('C:\\repo')).toBe('local');
    expect(kinds('file:///x')).toBe('local');
  });
});
